        {
          "matrix": {
            "os":   ["ubuntu-latest", "windows-latest"],   # dimensions...
            "node": [18, 20],
            "include": [ { ... } ],                          # optional
            "exclude": [ { ... } ]                           # optional
          },
          "maxParallel": 4,        # optional -> max-parallel
          "failFast":   false,     # optional -> fail-fast (default true)
          "maxSize":    256        # optional, validation cap (default 256)
        }

