    $combos = Add-Includes -Combinations $combos -Includes $includes -DimensionKeys $dimKeys

    # When only includes were provided (no dimensions), the initial single empty
    # combination is meaningless and must be dropped.
    if ($dimensions.Count -eq 0) {
        $combos = @($combos | Where-Object { $_.Count -gt 0 })
    }

